if (reduced) return;
ctx.clearRect(0, 0, width, height);
const particles = []; for (let i = 0; i < 80; i++) particles.push({ x: Math.random(), y: Math.random(), r: 1 + Math.random() * 2, speed: 0.1 + Math.random() * 0.3, life: Math.random() });
let t = 0;
function draw() {
  if (reduced) return;
  ctx.clearRect(0, 0, width, height);
  ctx.globalAlpha = 0.5; ctx.fillStyle = '#8fb080';
  for (const p of particles) {
    const y = (p.y - t * p.speed * 0.0003) % 1; if (y < 0) y += 1;
    const x = p.x * width + Math.sin(t * 0.0005 + p.life * 10) * 20;
    ctx.beginPath(); ctx.arc(x, y * height, p.r, 0, Math.PI * 2); ctx.fill();
  }
  ctx.globalAlpha = 1;
  t++; requestAnimationFrame(draw);
}
